draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W / 2, H / 2, 50, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2, H / 2 - 50);
  ctx.lineTo(W / 2, H / 2 - 100 + 20 * Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2 - 30, H / 2 - 20);
  ctx.lineTo(W / 2 - 60 + 20 * Math.cos(t), H / 2 + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2 + 30, H / 2 - 20);
  ctx.lineTo(W / 2 + 60 - 20 * Math.cos(t), H / 2 + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2, H / 2 + 50);
  ctx.lineTo(W / 2, H / 2 + 100 - 20 * Math.sin(t));
  ctx.stroke();
  ctx.font = '30px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Yay!', W / 2, H / 2 + 120 + 10 * Math.sin(t));
  ctx.restore();
}
